    [Xunit.Fact]
    public static void TestNoFusionOutsideTriggeredImagePages() {
        emon.Testport.AssertEq(Ofuse.OfActive(0, 1, 1), 0, "PDF and born digital never fuse");
        emon.Testport.AssertEq(Ofuse.OfActive(1, 0, 1), 0, "untriggered image never fuses");
        emon.Testport.AssertEq(Ofuse.OfActive(1, 1, 0), 0, "keyword gate is stacked");
        emon.Testport.AssertEq(Ofuse.OfActive(1, 1, 1), 1, "photo lane");
        emon.Testport.AssertEq(Ofuse.OfActive(1, 2, 1), 1, "thermal lane");
    }
    [Xunit.Fact]
    public static void TestValidNumericIncumbentIsProtected() {
        emon.Testport.AssertEq(Ofuse.OfRule(1, 1, 1, 1, 1, 3, 0, 1000, 0), 4, "even unanimous perfect alternate cannot replace a valid number");
    }
    [Xunit.Fact]
    public static void TestNumericCandidatesMustBeFormatValid() {
        emon.Testport.AssertEq(Ofuse.OfRule(1, 1, 0, 0, 1, 3, 0, 1000, 0), 4, "confidence and votes cannot admit malformed numbers");
    }
    [Xunit.Fact]
    public static void TestAlphaCandidatesNeedDictionaryOrAgreement() {
        emon.Testport.AssertEq(Ofuse.OfRule(1, 0, 0, 0, 0, 1, 0, 1000, 0), 5, "unflagged high confidence is insufficient");
        emon.Testport.AssertEq(Ofuse.OfRule(1, 0, 0, 0, 1, 1, 0, 900, 600), 2, "dictionary permits exact margin");
        emon.Testport.AssertEq(Ofuse.OfRule(1, 0, 0, 0, 0, 2, 0, 500, 900), 1, "agreement can replace despite negative margin");
    }
    [Xunit.Fact]
    public static void TestAgreementMustBeatIncumbentVotes() {
