        emon.Testport.AssertEq(Ofuse.OfRule(1, 0, 0, 0, 0, 2, 1, 700, 700), 1, "strictly more agreeing readings");
    }
    [Xunit.Fact]
    public static void TestSingleReadingReplacementNeedsMargin300() {
        emon.Testport.AssertEq(Ofuse.OfRule(1, 1, 0, 1, 0, 1, 0, 899, 600), 0, "299 keeps");
        emon.Testport.AssertEq(Ofuse.OfRule(1, 1, 0, 1, 0, 1, 0, 900, 600), 2, "300 replaces");
